const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Brazil region (representative area in Mato Grosso)
  const geometry = ee.Geometry.Point([-55.0, -12.0]).buffer(50000); // 50km buffer

  // Get MODIS Land Cover data (MCD12Q1)
  const modis2003 = ee.ImageCollection('MODIS/006/MCD12Q1')
    .filterDate('2003-01-01', '2003-12-31');

  const modis2019 = ee.ImageCollection('MODIS/006/MCD12Q1')
    .filterDate('2019-01-01', '2019-12-31');

  // Check if collections have data
  const count2003 = modis2003.size().getInfo();
  const count2019 = modis2019.size().getInfo();

  console.log(`2003 Images: ${count2003}, 2019 Images: ${count2019}`);

  if (count2003 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the land cover classification (IGBP) - cropland = class 12
  const lc2003 = modis2003.first().select('LC_Type1');
  const lc2019 = modis2019.first().select('LC_Type1');

  // Create cropland masks (class 12)
  const cropland2003 = lc2003.eq(12);
  const cropland2019 = lc2019.eq(12);

  // Count cropland pixels
  const stats2003 = cropland2003.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2019 = cropland2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  });

  const count2003_px = stats2003.get('LC_Type1').getInfo();
  const count2019_px = stats2019.get('LC_Type1').getInfo();

  console.log(`2003 Cropland Pixels: ${count2003_px}`);
  console.log(`2019 Cropland Pixels: ${count2019_px}`);

  // Check for valid pixels
  if (count2003_px === null || count2019_px === null || 
      isNaN(count2003_px) || isNaN(count2019_px)) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (count2003_px === 0 && count2019_px === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Determine if cropland increased
  const increased = count2019_px > count2003_px;
  const changePercent = ((count2019_px - count2003_px) / count2003_px * 100).toFixed(1);

  console.log(`Change: ${changePercent}%`);

  if (increased) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
